# -*- coding: utf-8 -*-
import io, os, sys
P = r"D:\NovelApp\core\planning.py"
TMP = P + ".tmp"
s = io.open(P, encoding="utf-8").read()
if "STEP_PROMPTS.update" in s:
    print("ALREADY"); sys.exit(0)
# 插到 ask_step 之前
ANCHOR = "def ask_step(book, sid, extra=''):"
i = s.find(ANCHOR)
if i < 0:
    print("anchor missing"); sys.exit(1)
s = s[:i] + "\n# --- 按需 8 步的 prompt（有这个概念才做；每步先问判断问题）---\n\nSTEP_PROMPTS.update({\n    '05': (\n        '你在帮一位作者看同一设定的几种不同写法（只改气质，不改内容）。',\n        '做法：\\n'\n        '· 版本 A：作者现在的写法\\n'\n        '· 版本 B：气质相反的一版\\n'\n        '· 版本 C：极简大纲版（只留骨架）\\n'\n        '\\n'\n        '铁律：机制和因果一字不动，只改口吻、节奏、密度。\\n'\n        '\\n'\n        '输出格式：\\n## 版本 A（现有气质）\\n## 版本 B（相反气质）\\n## 版本 C（骨架）\\n'\n        '\\n最后写一段「三个版本的差别在哪」，说明改的是哪几项。\\n'\n    ),\n    '06': (\n        '你在帮一位作者设计能力体系。',\n        '必须回答：\\n'\n        '· 强是怎么来的（从哪获取）\\n'\n        '· 一共分几级\\n'\n        '· 每一级要跨过什么门槛\\n'\n        '· 每一级有什么代价或风险\\n'\n        '· 什么限制了他的上限\\n'\n        '\\n'\n        '输出格式：\\n## 来源\\n## 分级\\n## 门槛\\n## 代价\\n## 上限\\n'\n        '\\n'\n        '铁律：不许照搬别的书的分级名（不写「练气筑基金丹」这类现成套路），\\n'\n        '分级名由这本书的规则自己长出来。如果作者已给了名称，就用他的。\\n'\n    ),\n    '07': (\n        '你在帮一位作者想清楚主角的「别人没有的东西」。',\n        '不一定是系统。可能是天赋 / 身份 / 消息渠道 / 别人不知道的记忆 / 一个愿意帮他的人。\\n'\n        '\\n'\n        '必须回答：\\n'\n        '· 这个东西具体能做什么、不能做什么\\n'\n        '· 它有什么代价或反噬\\n'\n        '· 别人会不会想抢\\n'\n        '· 它会在什么时候失效\\n'\n        '\\n'\n        '输出格式：\\n## 是什么\\n## 能做什么 / 不能做什么\\n## 代价\\n## 谁会想抢\\n## 什么时候失效\\n'\n    ),\n    '08': (\n        '你在帮一位作者出几种不同的开局方案。',\n        '出 3-5 种，每种说清：\\n'\n        '· 第一段是什么画面\\n'\n        '· 读者第一眼看到主角在做什么\\n'\n        '· 这个开头承诺了什么（读者会期待什么）\\n'\n        '· 它的风险（可能劝退哪类读者）\\n'\n        '\\n'\n        '输出格式：\\n### 方案 1：<一句话>\\n- 第一段：…\\n- 承诺：…\\n- 风险：…\\n'\n        '\\n只出方案，不推荐。选哪个由作者定。\\n'\n    ),\n    '09': (\n        '你在帮一位作者做群像。',\n        '必须回答：\\n'\n        '· 有哪些阵营/立场\\n'\n        '· 每个人想要什么\\n'\n        '· 他们之间谁和谁有旧账\\n'\n        '· 谁会背叛，为了什么\\n'\n        '\\n'\n        '输出格式：\\n## 阵营\\n## 各自要什么\\n## 旧账表\\n| 谁 | 和谁 | 什么旧账 |\\n## 可能的背叛\\n'\n    ),\n    '10': (\n        '你在帮一位作者定文笔模板，保证全书写法一致。',\n        '从作者已有正文里提取，不要凭空定：\\n'\n        '· 句子长度习惯（短句为主还是长句）\\n'\n        '· 段落长度\\n'\n        '· 对话密度\\n'\n        '· 用不用比喻、从哪取\\n'\n        '· 情绪怎么写（直说 / 靠动作 / 靠环境）\\n'\n        '\\n'\n        '输出格式：\\n## 句长\\n## 段长\\n## 对话密度\\n## 比喻\\n## 情绪写法\\n'\n        '\\n每条都要引用一句现有正文做证据，不许只给结论。\\n'\n    ),\n    '11': (\n        '你在帮一位写网络连载的作者做黄金三章。',\n        '必须回答：\\n'\n        '· 第一章要给读者什么（钩子 / 身份 / 处境）\\n'\n        '· 第二章推进什么\\n'\n        '· 第三章留下什么\\n'\n        '· 三章之内必须出现的东西（冲突 / 目标 / 代价）\\n'\n        '\\n'\n        '输出格式：\\n## 第一章\\n## 第二章\\n## 第三章\\n## 三章必须出现的\\n'\n        '\\n'\n        '提醒：这一整套规矩是平台机制推导出来的，不是写作本身的规律。\\n'\n        '如果作者写的是出版/短篇/纯文学，这套不适用。\\n'\n    ),\n    '13': (\n        '你在帮一位作者给配角做专项（5 个以上有戏份的配角）。',\n        '为每个人回答：\\n'\n        '· 表面上是什么人\\n'\n        '· 实际上是什么人\\n'\n        '· 他的专属特点（一个癖好 / 一句口头禅 / 一个习惯）\\n'\n        '· 他自己想要什么（和主角无关的）\\n'\n        '· 他藏了什么秘密\\n'\n        '· 他最后会怎样\\n'\n        '\\n'\n        '输出格式：每个配角一节，六条齐全。\\n'\n        '\\n如果作者素材里只有 2-3 个配角，就只做这几个，不要硬凑到 5 个。\\n'\n    ),\n})\n" + chr(10) + chr(10) + s[i:]
# 放宽 ask_step 的白名单
s = s.replace("'\u8fd9\u4e00\u6b65\u8fd8\u6ca1\u6709 AI \u8f85\u52a9\uff08\u73b0\u5728\u652f\u6301 01/02/03/04/12\uff09'", "'\u672a\u77e5\u6b65\u9aa4\uff1a' + str(sid)")
io.open(TMP, "w", encoding="utf-8", newline="").write(s)
os.replace(TMP, P)
print("ondemand prompts added")